<template>
  <div class="mobile-media-detail-container">

    <!-- 媒体展示区域（图片或视频） -->
    <div class="media-display-container">
      <div class="media-mask-group">
        <!-- 视频展示 -->
        <template v-if="isVideoMode">
          <l-video 
            v-if="adaptedMediaData.videoUrl"
            :src="adaptedMediaData.videoUrl" 
            w="100%" 
            h="100%" 
            fit="contain"
            :showControls="true"
            :muted="false"
            :preload="'metadata'"
            class="detail-video"
            @error="handleVideoError"
            @loadedmetadata="handleVideoLoaded"
          />
          <!-- 视频加载失败占位 -->
          <div v-else class="media-placeholder">
            <div class="placeholder-content">
              <span>{{ t('videoNotAvailable') }}</span>
            </div>
          </div>
        </template>
        
        <!-- 图片展示 -->
        <template v-else>
          <mobile-img 
            v-if="adaptedMediaData.imageUrl"
            :src="adaptedMediaData.imageUrl" 
            w="100%" 
            h="100%" 
            fit="cover"
            class="detail-image"
            @error="handleImageError"
          />
          <!-- 图片加载失败占位 -->
          <div v-else class="media-placeholder">
            <div class="placeholder-content">
              <span>{{ t('imageNotAvailable') }}</span>
            </div>
          </div>
        </template>
      </div>
    </div>
    
    <!-- Basemap区域（仅图生视频模式显示） -->
    <div v-if="showBasemap && adaptedMediaData.sourceImage" class="basemap-section">
      <h3 class="section-title">{{ t('basemap') }}</h3>
      <div class="basemap-container">
        <mobile-img 
          :src="adaptedMediaData.sourceImage" 
          w="100%" 
          h="192px" 
          fit="cover"
          class="basemap-image"
          @error="handleImageError"
        />
      </div>
    </div>
    
    <!-- Prompt区域 -->
    <div v-if="adaptedMediaData.prompt" class="prompt-section">
      <div class="prompt-header">
        <div class="section-title">{{ t('prompt') }}</div>
        <button class="copy-button" @click="handleCopyPrompt">
          <mobile-img 
            src="/static/images/copy_icon.png" 
            w="12px" 
            h="12px" 
            class="copy-icon"
          />
          <span class="copy-text">{{ t('copy') }}</span>
        </button>
      </div>
      <div class="prompt-container">
        <p class="prompt-text" :title="adaptedMediaData.prompt">{{ adaptedMediaData.prompt }}</p>
      </div>
    </div>
    
    <!-- Generation Details区域 -->
    <div v-if="visibleFields.length > 0" class="generation-details">
      <div class="section-title">{{ t('generationDetails') }}</div>
      <div class="detail-fields">
        <!-- 动态渲染有值的字段 -->
        <div 
          v-for="field in visibleFields" 
          :key="field"
          class="detail-field"
        >
          <span class="field-label">{{ getFieldLabel(field) }}</span>
          <span class="field-value">{{ getFieldValue(field) }}</span>
        </div>
      </div>
    </div>
    
    <!-- 底部安全区域 -->
    <div class="safe-area-bottom"></div>
  </div>
</template>

<script setup>
import { ref, computed, onMounted, onUnmounted, nextTick } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { useI18n } from 'vue-i18n';
import MobileImg from '@/mobile/components/mobile-l-img.vue';
import LVideo from '@/mobile/components/mobile-l-video.vue';
import { copy } from '@/utils/util.js';
import { showUIFeedback } from '@/utils/mobile-ui-feedback.js';
import { GenerationType } from '@/types/enums';
import { useMediaListStore } from '@/store/modules/media-list';

// 多语言和路由
const { t } = useI18n();
const route = useRoute();
const router = useRouter();

// 媒体数据store
const mediaStore = useMediaListStore();

// 响应式数据
const mediaData = ref({});
const mode = ref(GenerationType.TEXT_TO_IMAGE);
const loading = ref(false);



// 从store或路由参数获取数据
const initializeData = () => {
  console.log('Initializing media detail data...');
  
  try {
    // 1. 优先从store获取当前媒体详情数据
    const storeMediaData = mediaStore.getCurrentMediaDetail;
    const storeGenerationMode = mediaStore.getCurrentGenerationMode;
    
    if (storeMediaData && route.params.id && mediaStore.isCurrentMedia(route.params.id)) {
      console.log('Loading data from store:', storeMediaData);
      
      mediaData.value = storeMediaData;
      
      // 设置生成模式
      if (storeGenerationMode) {
        mode.value = storeGenerationMode;
      } else {
        // 根据数据类型自动设置模式
        const dataType = storeMediaData.mediaType || 
                        storeMediaData.originalApiData?.media_type ||
                        storeMediaData.media_type;
        
        if (dataType === 'video') {
          const generationType = storeMediaData.generationType || 
                               storeMediaData.originalApiData?.generation_type;
          if (generationType === 'image_to_video') {
            mode.value = GenerationType.IMAGE_TO_VIDEO;
          } else {
            mode.value = GenerationType.TEXT_TO_VIDEO;
          }
        } else {
          mode.value = GenerationType.TEXT_TO_IMAGE;
        }
      }
      
      console.log('Mode set from store:', mode.value);
      return;
    }
    
    // 2. 如果store没有数据或ID不匹配，尝试从路由参数获取基本信息
    if (route.params.id) {
      console.log('Store data not available, loading data by ID:', route.params.id);
      
      // 设置基本信息
      mode.value = route.query.mode || GenerationType.TEXT_TO_IMAGE;
      
      // 根据ID加载完整数据
      loadDataById(route.params.id);
    } else {
      console.warn('No media data or ID available');
    }
  } catch (error) {
    console.error('Error initializing media data:', error);
    
    // 降级到根据ID加载
    if (route.params.id) {
      loadDataById(route.params.id);
    }
  }
};

// 根据ID加载数据（备用方案）
const loadDataById = async (id) => {
  try {
    loading.value = true;
    console.log('Loading data by ID:', id);
    
    // TODO: 根据具体需求实现API调用
    // const response = await ApiGeneration.getMediaDetail(id);
    // mediaData.value = response.data;
    
    // TODO: 实现真实的API调用加载详情数据
    console.warn(`Media detail for ID ${id} not found in cache, need to implement API call`);
    
  } catch (error) {
    console.error('Failed to load media data:', error);
    showUIFeedback.error(t('loadFailed'));
  } finally {
    loading.value = false;
  }
};

// 支持的详情模式配置
const DETAIL_MODES = {
  [GenerationType.TEXT_TO_IMAGE]: {
    title: 'imageDetails',
    fields: ['model', 'resolution', 'dimensions', 'seed', 'createdDate']
  },
  [GenerationType.TEXT_TO_VIDEO]: {
    title: 'videoDetails', 
    fields: ['model', 'resolution', 'duration', 'videoDimensions', 'frameRate', 'seed', 'createdDate']
  },
  [GenerationType.IMAGE_TO_VIDEO]: {
    title: 'videoDetails',
    fields: ['model', 'resolution', 'duration', 'videoDimensions', 'frameRate', 'seed', 'createdDate']
  }
};

// 字段标签映射
const FIELD_LABELS = {
  model: 'model',
  resolution: 'resolution', 
  dimensions: 'dimensions',
  videoDimensions: 'videoDimensions',
  duration: 'duration',
  frameRate: 'frameRate',
  seed: 'seed',
  createdDate: 'createdDate'
};

// 计算属性：适配媒体数据（处理API返回的原始数据结构）
const adaptedMediaData = computed(() => {
  const raw = mediaData.value;
  if (!raw) return {};
  
  // 优先使用originalApiData（原始API数据），如果没有则使用转换后的数据
  const apiData = raw.originalApiData || raw;
  const baseData = {};
  
  console.log('Processing raw data:', raw);
  console.log('Using API data:', apiData);
  
  // 媒体URL处理
  if (raw.imageUrl) {
    baseData.imageUrl = raw.imageUrl;
  } else if (apiData.file_url && (apiData.media_type === 'image' || raw.mediaType === 'image')) {
    baseData.imageUrl = apiData.file_url;
  }
  
  if (raw.videoUrl) {
    baseData.videoUrl = raw.videoUrl;
  } else if (apiData.file_url && (apiData.media_type === 'video' || raw.mediaType === 'video')) {
    baseData.videoUrl = apiData.file_url;
  }
  
  // 原始图片处理（图生视频专用）
  if (apiData.media_metadata?.source_image) {
    baseData.sourceImage = apiData.media_metadata.source_image;
  } else if (raw.sourceImage) {
    baseData.sourceImage = raw.sourceImage;
  }
  
  // Prompt处理 - 优先使用原始API数据
  if (apiData.prompt) {
    baseData.prompt = apiData.prompt;
  } else if (apiData.media_metadata?.prompt) {
    baseData.prompt = apiData.media_metadata.prompt;
  } else if (raw.prompt) {
    baseData.prompt = raw.prompt;
  }
  
  // Model处理 - 优先使用原始API数据的顶级字段
  if (apiData.model) {
    baseData.model = apiData.model;
  } else if (apiData.media_metadata?.model) {
    baseData.model = apiData.media_metadata.model;
  } else if (raw.model) {
    baseData.model = raw.model;
  }
  
  // 分辨率处理 - 只在有真实数据时设置
  if (raw.resolution) {
    baseData.resolution = raw.resolution;
  } else if (apiData.media_metadata?.width && apiData.media_metadata?.height) {
    baseData.resolution = `${apiData.media_metadata.width}x${apiData.media_metadata.height}`;
  }
  // 如果没有真实分辨率数据，不设置此字段，不再推断
  
  // 尺寸比例处理 - 图片用dimensions，视频用videoDimensions
  if (raw.dimensions) {
    baseData.dimensions = raw.dimensions;
    baseData.videoDimensions = raw.dimensions;
  } else if (apiData.media_metadata?.aspect_ratio) {
    baseData.dimensions = apiData.media_metadata.aspect_ratio;
    baseData.videoDimensions = apiData.media_metadata.aspect_ratio;
  }
  
  // 视频时长处理
  if (apiData.media_metadata?.duration) {
    baseData.duration = `${apiData.media_metadata.duration}s`;
  }
  
  // 帧率处理 - 视频专用，只在有数据时设置
  if (raw.frameRate) {
    baseData.frameRate = raw.frameRate;
  } else if (apiData.media_metadata?.fps) {
    baseData.frameRate = `${apiData.media_metadata.fps} FPS`;
  } else if (apiData.media_metadata?.frame_rate) {
    baseData.frameRate = `${apiData.media_metadata.frame_rate} FPS`;
  }
  // 如果都没有，不设置 frameRate 字段
  
  // Seed处理 - 只在有真实数据时设置
  if (raw.seed !== undefined && raw.seed !== null && raw.seed !== '') {
    baseData.seed = raw.seed;
  }
  // 如果没有真实seed数据，不设置此字段
  
  // 创建日期处理 - 优先使用原始API数据的created_at字段
  if (apiData.created_at) {
    baseData.createdDate = apiData.created_at;
  } else if (raw.createdDate) {
    baseData.createdDate = raw.createdDate;
  }
  
  // 媒体类型处理
  if (apiData.media_type) {
    baseData.mediaType = apiData.media_type;
  } else if (raw.mediaType) {
    baseData.mediaType = raw.mediaType;
  }
  
  console.log('Final adapted media data:', baseData);
  return baseData;
});

// 计算属性：当前模式配置
const currentModeConfig = computed(() => {
  return DETAIL_MODES[mode.value] || DETAIL_MODES[GenerationType.TEXT_TO_IMAGE];
});

// 计算属性：可见字段（只显示有值的字段）
const visibleFields = computed(() => {
  return currentModeConfig.value.fields.filter(field => {
    const value = adaptedMediaData.value[field];
    return value !== undefined && value !== null && value !== '';
  });
});

// 计算属性：是否为视频模式
const isVideoMode = computed(() => {
  const videoModes = [GenerationType.TEXT_TO_VIDEO, GenerationType.IMAGE_TO_VIDEO];
  const isModeVideo = videoModes.includes(mode.value);
  const isDataVideo = adaptedMediaData.value.mediaType === 'video';
  const hasVideoUrl = !!adaptedMediaData.value.videoUrl;
  
  const result = isModeVideo || isDataVideo || hasVideoUrl;
  console.log('Video mode check:', {
    mode: mode.value,
    isModeVideo,
    isDataVideo,
    hasVideoUrl,
    result
  });
  
  return result;
});

// 计算属性：是否显示Basemap区域（仅图生视频模式）
const showBasemap = computed(() => {
  return mode.value === GenerationType.IMAGE_TO_VIDEO;
});

// 获取字段标签
const getFieldLabel = (field) => {
  return t(FIELD_LABELS[field] || field);
};

// 获取字段值
const getFieldValue = (field) => {
  const value = adaptedMediaData.value[field];
  
  // 特殊处理日期字段
  if (field === 'createdDate' && value) {
    return formatDate(value);
  }
  
  return value;
};

// 日期格式化 - 输出格式：June 23, 2025
const formatDate = (date) => {
  try {
    if (!date) return '';
    
    // 处理ISO 8601格式的日期字符串 (如: "2025-06-30T03:35:27Z")
    const dateObj = new Date(date);
    
    // 检查日期是否有效
    if (isNaN(dateObj.getTime())) {
      console.warn('Invalid date:', date);
      return date;
    }
    
    // 格式化为 "June 23, 2025" 格式
    return dateObj.toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'long', 
      day: 'numeric'
    });
  } catch (error) {
    console.warn('Date format error:', error);
    return date;
  }
};

// 复制Prompt功能
const handleCopyPrompt = async () => {
  try {
    await copy(adaptedMediaData.value.prompt);
    showUIFeedback.success(t('copySuccess'));
  } catch (error) {
    console.error('Copy failed:', error);
    showUIFeedback.error(t('copyFailed'));
  }
};

// 图片加载错误处理
const handleImageError = (error) => {
  console.warn('Image load error:', error);
};

// 视频加载错误处理
const handleVideoError = (error) => {
  console.warn('Video load error:', error);
};

// 视频加载完成处理
const handleVideoLoaded = (event) => {
  console.log('Video loaded successfully:', event);
};

// 返回按钮处理
const handleGoBack = () => {
  console.log('Going back...');
  router.back();
};



// 初始化
onMounted(() => {
  console.log('Media detail page mounted');
  console.log('Current route query:', route.query);
  console.log('Current route params:', route.params);
  
  initializeData();
  
  // 延迟输出以确保数据已经加载
  nextTick(() => {
    console.log('Media data:', mediaData.value);
    console.log('Mode:', mode.value);
    console.log('Is video mode:', isVideoMode.value);
    console.log('Show basemap:', showBasemap.value);
    console.log('Adapted data:', adaptedMediaData.value);
    console.log('Visible fields:', visibleFields.value);
  });
});

// 页面卸载时清空当前媒体数据
onUnmounted(() => {
  console.log('Media detail page unmounted, clearing current media data');
  mediaStore.clearCurrentMediaDetail();
});
</script>

